import unittest
from bounded import clamp_nonnegative

class ClampTests(unittest.TestCase):
    def test_positive(self):
        self.assertEqual(clamp_nonnegative(7), 7)
    def test_zero(self):
        self.assertEqual(clamp_nonnegative(0), 0)
    def test_negative(self):
        self.assertEqual(clamp_nonnegative(-4), 0)

if __name__ == '__main__':
    unittest.main()
